			function onGrdListSelectionChange(e){	
				var grdList = null;
				if(e == undefined){
					grdList = app.lookup('grdList');
				}else{		
					grdList = e.control;	
				}
				var init = false;
				//console.log("Selected Row Changed",grdList.getSelectedRow().getRowData().CNSLTNT_ID);
				if(grdList.getSelectedRow() == null || grdList.getSelectedRow() == undefined){
					util.DataSet.clear(app, 'dsList2');
					util.Control.reset(app, 'grp1');
					util.Control.redraw(app, 'grp1');
					//return;
					init = true;
				}
				if(!init){
					app.lookup("dmSearch").setValue("USER_ID", grdList.getSelectedRow().getRowData().CNSLTNT_ID);		
				}else{
					app.lookup("dmSearch").setValue("USER_ID",null);
				}
					
				util.Submit.send(app, "subList2", function(pbSuccess) {
					if(pbSuccess){
						//조회되었습니다.
						util.Msg.notify(app, "INF-M001");
					}
				});
				
			}

